/**
 * One-off investigation script (**read-only**): identify one-off leftover test databases on VDB that can be safely cleaned up.
 *
 * Background: the instance collection count has hit the cap of 1500/1500, so new databases cannot be created. Test leftovers must be reclaimed first.
 *
 * Criteria (only databases with **explicit one-off test characteristics** are recognized; better to miss than to hit wrongly):
 *   - `memory-tdai-test-*`        generated by automated e2e, with a random run id in the name
 *   - `verify_memory_bm25_*`      generated by the BM25 verification script, with a timestamp in the name
 *   - `clearverify-*`             generated by this clear verification script
 *   - `*_probe` / `*probe*`       temporary databases used for probing
 *
 * Explicitly **excluded** (may be long-lived environments in use by others):
 *   - memory-tencentdb-testing-*  shared test databases
 *   - memory_dev_*               development environment databases
 *   - everything else that does not match the above patterns
 *
 * This script only outputs the list and statistics, and **performs no deletion**.
 */
import { TcvdbClient } from "../src/core/store/tcvdb/client.js";

const VDB_URL = process.env.VDB_URL;
const VDB_API_KEY = process.env.VDB_API_KEY;

if (!VDB_URL || !VDB_API_KEY) {
  console.error("Environment variables VDB_URL / VDB_API_KEY are required");
  process.exit(2);
}

const silent = { debug: () => {}, info: () => {}, warn: () => {}, error: () => {} };

/** Explicit characteristics of one-off test databases. */
const DISPOSABLE_PATTERNS: Array<{ name: string; test: (db: string) => boolean }> = [
  { name: "memory-tdai-test-*", test: (d) => d.startsWith("memory-tdai-test-") },
  { name: "verify_memory_bm25_*", test: (d) => d.startsWith("verify_memory_bm25_") },
  { name: "clearverify-*", test: (d) => d.startsWith("clearverify-") },
];

/** Explicitly protected, never included in the cleanup list. */
const PROTECTED_PATTERNS: Array<(db: string) => boolean> = [
  (d) => d.startsWith("memory-tencentdb-testing"),
  (d) => d.startsWith("memory_dev_"),
];

function classify(db: string): { disposable: boolean; reason: string } {
  for (const p of PROTECTED_PATTERNS) {
    if (p(db)) return { disposable: false, reason: "protected" };
  }
  for (const p of DISPOSABLE_PATTERNS) {
    if (p.test(db)) return { disposable: true, reason: p.name };
  }
  return { disposable: false, reason: "unknown-keep" };
}

async function main() {
  const client = new TcvdbClient({
    url: VDB_URL!,
    username: process.env.VDB_USERNAME ?? "root",
    apiKey: VDB_API_KEY!,
    database: process.env.VDB_DATABASE ?? "default",
    timeout: 30_000,
    logger: silent,
  });

  const dbResp = await client.request<{ databases?: string[] }>("/database/list", {});
  const dbs = dbResp.databases ?? [];

  let totalCols = 0;
  let reclaimable = 0;
  const byReason = new Map<string, { dbs: number; cols: number }>();
  const keepUnknown: string[] = [];

  for (const db of dbs) {
    let n = 0;
    try {
      const r = await client.request<{ collections?: Array<{ collection?: string }> }>(
        "/collection/list", { database: db },
      );
      n = (r.collections ?? []).length;
    } catch { /* if it can't be counted, count it as 0 */ }
    totalCols += n;

    const { disposable, reason } = classify(db);
    const slot = byReason.get(reason) ?? { dbs: 0, cols: 0 };
    slot.dbs++;
    slot.cols += n;
    byReason.set(reason, slot);

    if (disposable) reclaimable += n;
    else if (reason === "unknown-keep") keepUnknown.push(db);
  }

  console.log(`Total databases: ${dbs.length}`);
  console.log(`Total collections: ${totalCols} / 1500 (headroom ${1500 - totalCols})\n`);

  console.log("Statistics by category:");
  for (const [reason, s] of [...byReason.entries()].sort((a, b) => b[1].cols - a[1].cols)) {
    const tag = DISPOSABLE_PATTERNS.some((p) => p.name === reason) ? "reclaimable" : "keep";
    console.log(`  [${tag}] ${reason.padEnd(24)} ${String(s.dbs).padStart(4)} dbs${String(s.cols).padStart(5)} collections`);
  }

  console.log(`\nReclaimable collections: ${reclaimable} (headroom after cleanup about ${1500 - totalCols + reclaimable})`);
  console.log(`Unrecognized databases conservatively kept: ${keepUnknown.length}`);
  if (keepUnknown.length) console.log(`  Examples: ${keepUnknown.slice(0, 10).join(", ")}`);
}

main().catch((err) => {
  console.error("probe failed:", err instanceof Error ? err.message : String(err));
  process.exitCode = 1;
});
